B.Ll=new A.ea("Tree DFS & Path Traversals","Trees","O(V + E) = O(n)","O(h) stack space",B.S4,"def tree_dfs(root):\n    max_diameter = 0\n\n    def depth(node):\n        nonlocal max_diameter\n        if not node:\n            return 0\n        left = depth(node.left)\n        right = depth(node.right)\n\n        # Invariant check: diameter through current node\n        max_diameter = max(max_diameter, left + right)\n\n        # Return height contribution to parent\n        return 1 + max(left, right)\n\n    depth(root)\n    return max_diameter",B.S3,B.TY)
