B.Lr=new A.ea("Binary Search Tree (BST) Invariants","Trees","O(h) where h = log n","O(h)",B.Vp,"def is_valid_bst(root):\n    def validate(node, low=float('-inf'), high=float('inf')):\n        if not node:\n            return True\n        if not (low < node.val < high):\n            return False\n        return (validate(node.left, low, node.val) and\n                validate(node.right, node.val, high))\n\n    return validate(root)",B.Ra,B.T6)
